object Plot {
    data class Cell(val col: Int,val row: Int)
    fun canvas(width: Int,height: Int)=Array(height) {
        CharArray(width) {
            ' '
        }
    }
    fun map(point: Predicates.Point,width: Int,height: Int)=Cell(((2*point.x*(width-1)+1000)/2000).toInt(),height-1-((2*point.y*(height-1)+1000)/2000).toInt())
    fun center(point: Predicates.Center,width: Int,height: Int)=Cell(((2*point.x*(width-1)+1000*point.d)/(2000*point.d)).toInt(),
        height-1-((2*point.y*(height-1)+1000*point.d)/(2000*point.d)).toInt())
    fun line(grid: Array<CharArray>,from: Cell,to: Cell,ch: Char) {
        var x=from.col;
        var y=from.row;
        val dx=abs(to.col-x);
        val dy=-abs(to.row-y);
        val sx=if(x<to.col)1 else -1;
        val sy=if(y<to.row)1 else -1;
        var e=dx+dy;
        while(true) {
            grid[y][x]=ch;
            if(x==to.col&&y==to.row)break;
            val e2=2*e;
            if(e2>=dy) {
                e+=dy;
                x+=sx
            };
            if(e2<=dx) {
                e+=dx;
                y+=sy
            }
        }
    }
    fun frame(grid: Array<CharArray>): List<String> {
        val border="+"+"-".repeat(grid[0].size)+"+";
        val result=mutableListOf(border);
        for(row in grid)result+="|"+row.concatToString()+"|";
        result+=border;
        return result
    }
    fun voronoi(points: List<Predicates.Point>,width: Int,height: Int): Array<CharArray> {
        val grid=canvas(width,height);
        val owners=Array(height) {
            IntArray(width)
        };
        for(row in 0 until height)for(col in 0 until width) {
            var best=Long.MAX_VALUE;
            var owner=0;
            for(site in 1 until points.size) {
                val p=points[site];
                val x=(col*1000-p.x*(width-1))*(height-1);
                val y=((height-1-row)*1000-p.y*(height-1))*(width-1);
                val delta=x*x+y*y;
                if(delta<best) {
                    best=delta;
                    owner=site
                }
            };
            owners[row][col]=owner
        };
        for(row in 0 until height)for(col in 0 until width)if(col+1<width&&owners[row][col]!=owners[row][col+1]||row+1<height&&owners[row][col]!=owners[row+1][col])grid[row][col]='#';
        for(site in 1 until points.size) {
            val cell=map(points[site],width,height);
            grid[cell.row][cell.col]='o'
        };
        return grid
    }
}

import kotlin.math.abs

object Predicates {
    data class Point(val x: Long,val y: Long)
    data class Center(val x: Long,val y: Long,val d: Long)
    fun orient(p: Point,q: Point,r: Point)=(q.x-p.x)*(r.y-p.y)-(q.y-p.y)*(r.x-p.x)
    fun d2(p: Point,q: Point): Long {
        val x=p.x-q.x;
        val y=p.y-q.y;
        return x*x+y*y
    }
    fun dot(o: Point,p: Point,q: Point)=(p.x-o.x)*(q.x-o.x)+(p.y-o.y)*(q.y-o.y)
    fun incircle(a: Point,b: Point,c: Point,d: Point): Long {
        val ax=a.x-d.x;
        val ay=a.y-d.y;
        val bx=b.x-d.x;
        val by=b.y-d.y;
        val cx=c.x-d.x;
        val cy=c.y-d.y;
        val aa=ax*ax+ay*ay;
        val bb=bx*bx+by*by;
        val cc=cx*cx+cy*cy;
        return ax*(by*cc-bb*cy)-ay*(bx*cc-bb*cx)+aa*(bx*cy-by*cx)
    }
    fun center(a: Point,b: Point,c: Point): Center {
        val bx=b.x-a.x;
        val by=b.y-a.y;
        val cx=c.x-a.x;
        val cy=c.y-a.y;
        val bb=bx*bx+by*by;
        val cc=cx*cx+cy*cy;
        val d=2*(bx*cy-by*cx);
        return Center(a.x*d+cy*bb-by*cc,a.y*d+bx*cc-cx*bb,d)
    }
    fun gcd(a0: Long,b0: Long): Long {
        var a=abs(a0);
        var b=abs(b0);
        while(b!=0L) {
            val rest=a%b;
            a=b;
            b=rest
        };
        return a
    }
    fun fraction(n0: Long,d0: Long): String {
        val g=gcd(n0,d0);
        val n=n0/g;
        val d=d0/g;
        return if(d==1L)n.toString() else "$n/$d"
    }
    fun reduce(x: Long,y: Long): Point {
        val g=gcd(x,y);
        return Point(x/g,y/g)
    }
}

import kotlin.math.sqrt

object Proximity {
    class Sets(n: Int) {
        val parent=IntArray(n+1) {
            it
        };
        val size=IntArray(n+1) {
            1
        };
        var count=n;
        fun find(i0: Int): Int {
            var i=i0;
            while(parent[i]!=i) {
                parent[i]=parent[parent[i]];
                i=parent[i]
            };
            return i
        };
        fun union(a0: Int,b0: Int): Boolean {
            var a=find(a0);
            var b=find(b0);
            if(a==b)return false;
            if(size[a]<size[b]) {
                val swap=a;
                a=b;
                b=swap
            };
            parent[b]=a;
            size[a]+=size[b];
            count--;
            return true
        }
    }
    fun nearest(points: List<Predicates.Point>,neighbors: List<List<Int>>): IntArray {
        val result=IntArray(points.size);
        for(s in 1 until points.size) {
            var best=0;
            var distance=Long.MAX_VALUE;
            for(t in neighbors[s]) {
                val candidate=Predicates.d2(points[s],points[t]);
                if(candidate<distance||candidate==distance&&t<best) {
                    best=t;
                    distance=candidate
                }
            };
            result[s]=best
        };
        return result
    }
    fun components(nearest: IntArray): List<List<Int>> {
        val sets=Sets(nearest.size-1)
        for(s in 1 until nearest.size)sets.union(s,nearest[s])
        val groups=mutableMapOf<Int,MutableList<Int>>()
        for(s in 1 until nearest.size) {
            val group=groups.getOrPut(sets.find(s)) { mutableListOf() }
            group.add(s)
        }
        return groups.values.sortedBy { it[0] }
    }
    fun mst(points: List<Predicates.Point>,edges: List<Triangulation.Edge>): List<Triangulation.Edge> {
        val ordered=edges.sortedWith(compareBy<Triangulation.Edge> {
            Predicates.d2(points[it.a],points[it.b])
        }.thenBy {
            it
        });
        val sets=Sets(points.size-1);
        return ordered.filter {
            sets.union(it.a,it.b)
        }
    }
    fun gabriel(points: List<Predicates.Point>,edge: Triangulation.Edge,directed: Map<Triangulation.Edge,Int>): Boolean {
        for(e in listOf(edge,Triangulation.Edge(edge.b,edge.a))) {
            val q=directed[e];
            if(q!=null&&Predicates.dot(points[q],points[edge.a],points[edge.b])<=0)return false
        };
        return true
    }
    fun rng(points: List<Predicates.Point>,edge: Triangulation.Edge): Boolean {
        val length=Predicates.d2(points[edge.a],points[edge.b]);
        for(k in 1 until points.size)if(Predicates.d2(points[edge.a],points[k])<length&&Predicates.d2(points[edge.b],points[k])<length)return false;
        return true
    }
    data class Route(val sites: List<Int>,val length: Double)
    fun route(points: List<Predicates.Point>,neighbors: List<List<Int>>,start: Int,target: Int): Route {
        val path=mutableListOf(start);
        var length=0.0;
        var current=start;
        while(current!=target) {
            var best=0;
            var distance=Long.MAX_VALUE;
            for(t in neighbors[current]) {
                val candidate=Predicates.d2(points[t],points[target]);
                if(candidate<distance||candidate==distance&&t<best) {
                    best=t;
                    distance=candidate
                }
            };
            length+=sqrt(Predicates.d2(points[current],points[best]).toDouble());
            path+=best;
            current=best
        };
        return Route(path,length)
    }
    data class Paths(val distance: DoubleArray,val previous: IntArray) {
        fun path(target: Int): List<Int> {
            val result=mutableListOf<Int>();
            var current=target;
            while(current!=0) {
                result+=current;
                current=previous[current]
            };
            result.reverse();
            return result
        }
    }
    fun dijkstra(points: List<Predicates.Point>,neighbors: List<List<Int>>,start: Int): Paths {
        val n=points.size-1;
        val distance=DoubleArray(n+1) {
            Double.POSITIVE_INFINITY
        };
        val previous=IntArray(n+1);
        val done=BooleanArray(n+1);
        distance[start]=0.0;
        for(step in 0 until n) {
            var site=0;
            for(s in 1..n)if(!done[s]&&(site==0||distance[s]<distance[site]))site=s;
            done[site]=true;
            for(t in neighbors[site]) {
                val candidate=distance[site]+sqrt(Predicates.d2(points[site],points[t]).toDouble());
                if(candidate<distance[t]) {
                    distance[t]=candidate;
                    previous[t]=site
                }
            }
        };
        return Paths(distance,previous)
    }
}

object Triangulation {
    data class Edge(val a: Int,val b: Int): Comparable<Edge> {
        override fun compareTo(other: Edge): Int {
            val c=a.compareTo(other.a);
            return if(c!=0)c else b.compareTo(other.b)
        }
    }
    data class Triangle(val a: Int,val b: Int,val c: Int): Comparable<Triangle> {
        override fun compareTo(other: Triangle): Int {
            var result=a.compareTo(other.a);
            if(result==0)result=b.compareTo(other.b);
            return if(result!=0)result else c.compareTo(other.c)
        };
        fun sites()=intArrayOf(a,b,c)
    }
    fun key(a: Int,b: Int)=Edge(minOf(a,b),maxOf(a,b))
    fun canonical(a: Int,b: Int,c: Int)=if(a<b&&a<c)Triangle(a,b,c) else if(b<c)Triangle(b,c,a) else Triangle(c,a,b)
    data class Insertion(val kind: String,val containing: Triangle?,val visible: Int,val flips: Int,val triangles: Int,val hull: Int)
    class Model(val points: List<Predicates.Point>) {
        val directed=mutableMapOf<Edge,Int>();
        val initial=if(Predicates.orient(points[1],points[2],points[3])>0)Triangle(1,2,3) else Triangle(1,3,2)
        init {
            add(initial.a,initial.b,initial.c)
        }
        fun add(a: Int,b: Int,c: Int) {
            directed[Edge(a,b)]=c;
            directed[Edge(b,c)]=a;
            directed[Edge(c,a)]=b
        }
        fun remove(a: Int,b: Int,c: Int) {
            directed.remove(Edge(a,b));
            directed.remove(Edge(b,c));
            directed.remove(Edge(c,a))
        }
        fun triangles()=directed.map {
            (edge,opposite)->canonical(edge.a,edge.b,opposite)
        }.toSortedSet().toList()
        fun hullEdges()=directed.keys.filter {
            Edge(it.b,it.a) !in directed
        }.sorted()
        fun insert(site: Int): Insertion {
            val containing=triangles().firstOrNull {
                t->Predicates.orient(points[t.a],points[t.b],points[site])>0&&Predicates.orient(points[t.b],
                    points[t.c],points[site])>0&&Predicates.orient(points[t.c],points[t.a],
                    points[site])>0
            };
            val check=sortedSetOf<Edge>();
            var visible=0;
            if(containing!=null) {
                val a=containing.a;
                val b=containing.b;
                val c=containing.c;
                remove(a,b,c);
                check+=Edge(a,b);
                check+=Edge(b,c);
                check+=Edge(c,a)
            } else {
                for(e in hullEdges())if(Predicates.orient(points[e.a],points[e.b],points[site])<0)check+=Edge(e.b,e.a);
                visible=check.size
            };
            for(e in check)add(e.a,e.b,site);
            var flips=0;
            while(check.isNotEmpty()) {
                val edge=check.first();
                check.remove(edge);
                val a=edge.a;
                val b=edge.b;
                val q=directed[Edge(b,a)];
                if(q!=null&&Predicates.incircle(points[a],points[b],points[site],points[q])>0) {
                    remove(a,b,site);
                    remove(b,a,q);
                    add(a,q,site);
                    add(q,b,site);
                    check+=Edge(a,q);
                    check+=Edge(q,b);
                    flips++
                }
            };
            return Insertion(if(containing==null)"outside" else "inside",containing,visible,flips,directed.size/3,hullEdges().size)
        }
    }
    data class Walk(val path: List<Int>,val outside: Edge?)
    fun walk(query: Predicates.Point,points: List<Predicates.Point>,triangles: List<Triangle>,directed: Map<Edge,Int>): Walk {
        val path=mutableListOf(1);
        while(true) {
            val t=triangles[path.last()-1];
            var moved=false;
            for(e in listOf(Edge(t.a,t.b),Edge(t.b,t.c),Edge(t.c,t.a)))if(Predicates.orient(points[e.a],points[e.b],query)<0) {
                val next=directed[Edge(e.b,e.a)]?:return Walk(path,key(e.a,e.b));
                path+=next;
                moved=true;
                break
            };
            if(!moved)return Walk(path,null)
        }
    }
}

object Voronoi {
    data class Vertex(val center: Predicates.Center,val r2: Double,val position: String)
    data class RealPoint(val x: Double,val y: Double)
    fun radius2(a: Predicates.Point,b: Predicates.Point,c: Predicates.Point): Double {
        val area=Predicates.orient(a,b,c);
        return ((Predicates.d2(a,b).toDouble()*Predicates.d2(b,c))*Predicates.d2(c,a))/((4.0*area)*area)
    }
    fun position(v: Predicates.Center,hull: List<Int>,points: List<Predicates.Point>): String {
        var on=false;
        for(i in hull.indices) {
            val a=points[hull[i]];
            val b=points[hull[(i+1)%hull.size]];
            val sigma=(b.x-a.x)*(v.y-a.y*v.d)-(b.y-a.y)*(v.x-a.x*v.d);
            if(sigma<0)return "outside";
            if(sigma==0L)on=true
        };
        return if(on)"on" else "inside"
    }
    fun outward(a: Predicates.Point,b: Predicates.Point)=Predicates.reduce(b.y-a.y,a.x-b.x)
    fun neighbors(site: Int,adjacent: List<Int>,directed: Map<Triangulation.Edge,Int>,next: Int?): List<Int> {
        val start=next?:adjacent.min();
        val result=mutableListOf<Int>();
        var current=start;
        while(true) {
            result+=current;
            val following=directed[Triangulation.Edge(site,current)];
            if(following==null||following==start)break;
            current=following
        };
        return result
    }
    fun area(site: Int,vertexIds: List<Int>,vertices: List<Vertex>,points: List<Predicates.Point>): Double {
        val origin=points[site];
        var sum=0.0;
        for(i in vertexIds.indices) {
            val a=vertices[vertexIds[i]-1].center;
            val b=vertices[vertexIds[(i+1)%vertexIds.size]-1].center;
            val u=a.x.toDouble()/a.d-origin.x;
            val w=a.y.toDouble()/a.d-origin.y;
            val un=b.x.toDouble()/b.d-origin.x;
            val wn=b.y.toDouble()/b.d-origin.y;
            sum+=u*wn-un*w
        };
        return sum/2
    }
    fun clipped(site: Int,neighbors: List<Int>,points: List<Predicates.Point>): Double {
        var polygon=listOf(RealPoint(0.0,0.0),RealPoint(1000.0,0.0),RealPoint(1000.0,1000.0),RealPoint(0.0,1000.0));
        val s=points[site];
        for(neighbor in neighbors) {
            val t=points[neighbor];
            val c1=2*(t.x-s.x);
            val c2=2*(t.y-s.y);
            val c3=t.x*t.x+t.y*t.y-s.x*s.x-s.y*s.y;
            val next=mutableListOf<RealPoint>();
            for(i in polygon.indices) {
                val a=polygon[i];
                val b=polygon[(i+1)%polygon.size];
                val fa=c1*a.x+c2*a.y-c3;
                val fb=c1*b.x+c2*b.y-c3;
                if(fa<=0)next+=a;
                if(fa<0&&fb>0||fb<0&&fa>0) {
                    val lambda=fa/(fa-fb);
                    next+=RealPoint(a.x+(b.x-a.x)*lambda,a.y+(b.y-a.y)*lambda)
                }
            };
            polygon=next
        };
        var sum=0.0;
        for(i in polygon.indices) {
            val a=polygon[i];
            val b=polygon[(i+1)%polygon.size];
            sum+=a.x*b.y-b.x*a.y
        };
        return sum/2
    }
}
